// SQLite comparator only; FlexDB itself is entirely Flexscript.
#include <sqlite3.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <sys/stat.h>
#include <sys/resource.h>
static sqlite3 *db;
static void check(int ok){if(!ok){fprintf(stderr,"%s\n",sqlite3_errmsg(db));exit(1);}}
static int64_t now(void){struct timespec t;clock_gettime(CLOCK_MONOTONIC,&t);return (int64_t)t.tv_sec*1000000000+t.tv_nsec;}
static void sql(const char *s){check(sqlite3_exec(db,s,0,0,0)==SQLITE_OK);}
static sqlite3_stmt *prepare(const char *s){sqlite3_stmt *p;check(sqlite3_prepare_v2(db,s,-1,&p,0)==SQLITE_OK);return p;}
static int64_t queries(sqlite3_stmt *p,int n,int count){int64_t start=now(),sum=0;for(int i=0;i<count;i++){check(sqlite3_bind_int64(p,1,((int64_t)i*7919)%n)==SQLITE_OK);check(sqlite3_step(p)==SQLITE_ROW);sum+=sqlite3_column_int64(p,0);check(sqlite3_step(p)==SQLITE_DONE);check(sqlite3_reset(p)==SQLITE_OK);}int64_t elapsed=now()-start;check(sum==count);return elapsed;}
int main(int argc,char **argv){if(argc!=3)return 1;int n=atoi(argv[2]);check(sqlite3_open_v2(argv[1],&db,SQLITE_OPEN_READWRITE|SQLITE_OPEN_CREATE|SQLITE_OPEN_NOMUTEX,0)==SQLITE_OK);sql("PRAGMA journal_mode=WAL; PRAGMA synchronous=FULL; PRAGMA cache_size=-65536; CREATE TABLE items(id INTEGER PRIMARY KEY,key INTEGER NOT NULL); BEGIN;");sqlite3_stmt *p=prepare("INSERT INTO items VALUES(?1,?2)");for(int i=0;i<n;i++){check(sqlite3_bind_int(p,1,i+1)==SQLITE_OK);check(sqlite3_bind_int(p,2,i)==SQLITE_OK);check(sqlite3_step(p)==SQLITE_DONE);check(sqlite3_reset(p)==SQLITE_OK);}sqlite3_finalize(p);sql("COMMIT; BEGIN;");p=prepare("SELECT count(*) FROM items WHERE key=?1");int64_t scan=queries(p,n,100);sqlite3_finalize(p);sql("COMMIT;");int64_t start=now();sql("CREATE INDEX items_key ON items(key);");int64_t build=now()-start;sql("BEGIN;");p=prepare("SELECT count(*) FROM items WHERE key=?1");int64_t indexed=queries(p,n,100000);sqlite3_finalize(p);sql("COMMIT;");p=prepare("UPDATE items SET key=?1 WHERE id=?2");start=now();sql("BEGIN;");for(int i=0;i<1000;i++){check(sqlite3_bind_int(p,1,n+i)==SQLITE_OK);check(sqlite3_bind_int(p,2,i+1)==SQLITE_OK);check(sqlite3_step(p)==SQLITE_DONE);check(sqlite3_changes(db)==1);check(sqlite3_reset(p)==SQLITE_OK);}sql("COMMIT;");int64_t update=now()-start;sqlite3_finalize(p);p=prepare("SELECT count(*) FROM items WHERE key=?1");check(sqlite3_bind_int(p,1,42)==SQLITE_OK);check(sqlite3_step(p)==SQLITE_ROW && sqlite3_column_int64(p,0)==0);check(sqlite3_reset(p)==SQLITE_OK);check(sqlite3_bind_int(p,1,n+42)==SQLITE_OK);check(sqlite3_step(p)==SQLITE_ROW && sqlite3_column_int64(p,0)==1);sqlite3_finalize(p);start=now();check(sqlite3_close(db)==SQLITE_OK);int64_t close=now()-start;struct stat st;check(stat(argv[1],&st)==0);start=now();check(sqlite3_open_v2(argv[1],&db,SQLITE_OPEN_READWRITE|SQLITE_OPEN_NOMUTEX,0)==SQLITE_OK);p=prepare("SELECT count(*) FROM items WHERE key=?1");check(sqlite3_bind_int(p,1,n+42)==SQLITE_OK);check(sqlite3_step(p)==SQLITE_ROW && sqlite3_column_int64(p,0)==1);int64_t reopen=now()-start;sqlite3_finalize(p);check(sqlite3_close(db)==SQLITE_OK);struct rusage usage;check(getrusage(RUSAGE_SELF,&usage)==0);printf("{\"scan_100_ns\":%lld,\"learn_build_ns\":%lld,\"indexed_100000_ns\":%lld,\"reopen_first_lookup_ns\":%lld,\"indexed_update_1000_ns\":%lld,\"checkpoint_close_ns\":%lld,\"bytes\":%lld,\"peak_kib\":%ld}\n",(long long)scan,(long long)build,(long long)indexed,(long long)reopen,(long long)update,(long long)close,(long long)st.st_size,usage.ru_maxrss);}
